/**
 * The Swift package's generated files: for each library, a Swift module with an `Icon` enum and
 * an asset catalogue holding each icon as an SVG.
 *
 * The SVGs are the same filled outlines the Pen libraries draw, 24 x 24 and filled black, marked
 * as template images that keep their vector data, so an app draws what the designs draw at any
 * size. Each case of `Icon` is an id of the library, with the id as its raw value; the catalogue
 * names its image by the id too.
 *
 * - An icon of the release, and a retired id (it keeps the outline it last had), is a case with
 *   an image of its own.
 * - A Lucide alias is a deprecated static member, renamed to the case of the icon it copies,
 *   so Xcode offers to rename uses of it. It has no image of its own.
 * - A lab alias copies a Lucide icon, which is in the other module, so it is a case with an image
 *   of its own, a copy of the Lucide icon's. Deprecated cases would stop Swift synthesising
 *   CaseIterable, so it is not deprecated; its comment says where the icon went.
 */
import { join } from 'node:path'

/** One id of a library, as the Pen library has it. */
export type Entry = {
	id: string
	geometry: string
	/** For an alias, the Lucide icon it copies. */
	alias?: string
	retired?: boolean
}

/** A Swift module of icons: its name, the Lucide release, and the library's ids. */
export type Module = {
	name: string
	release: string
	entries: Entry[]
	/** True when its aliases' icons are in the module (Lucide), false when in Lucide (lab). */
	ownAliases: boolean
}

const HEADER = '// Generated by tools/generate.ts from the pinned Lucide releases. Do not edit.\n'

// Swift's keywords, which a case name has to escape with backticks.
const KEYWORDS = new Set(
	(
		'associatedtype borrowing class consuming deinit enum extension fileprivate func import init ' +
		'inout internal let nonisolated open operator private precedencegroup protocol public ' +
		'rethrows static struct subscript typealias var break case catch continue default defer do ' +
		'else fallthrough for guard if in repeat return throw switch where while Any as await false ' +
		'is nil self Self super throws true try Type Protocol'
	).split(' ')
)

/** A problem with the names, reported by the generator without a stack trace. */
export class SwiftNameError extends Error {}

/** The Swift name of a Lucide id: lower camel case, `arrow-down-0-1` as `arrowDown01`. */
export function swiftName(id: string): string {
	if (!/^[a-z][a-z0-9]*(-[a-z0-9]+)*$/.test(id)) {
		throw new SwiftNameError(`${id} has no Swift name: ids are kebab case starting with a letter`)
	}
	return id
		.split('-')
		.map((part, k) => (k ? part[0]!.toUpperCase() + part.slice(1) : part))
		.join('')
}

/** A Swift name as it is written where it is declared: a keyword in backticks. */
const declared = (name: string) => (KEYWORDS.has(name) ? `\`${name}\`` : name)

// The members Icon has besides its ids, which no id may be named.
const MEMBERS = ['aliases', 'allCases', 'bundle', 'hashValue', 'id', 'nsImage', 'rawValue']
	.concat(['release', 'uiImage'])
	.map((m) => [m, `Icon's own ${m}`] as const)

/** Stops if two ids, or an id and one of Icon's own members, would have the same Swift name. */
function checkNames(module: Module) {
	const seen = new Map<string, string>(MEMBERS)
	for (const { id } of module.entries) {
		const name = swiftName(id)
		const other = seen.get(name)
		if (other) throw new SwiftNameError(`${other} and ${id} would both be ${module.name}.${name}`)
		seen.set(name, id)
	}
}

/** The argument label of the module's SwiftUI Image initialiser: Lucide's is `lucide`. */
export const label = (module: Module) => module.name[0]!.toLowerCase() + module.name.slice(1)

const count = (n: number) => n.toLocaleString('en-US')

/** Icon.swift: the enum of the module's icons and its aliases. */
export function iconSwift(module: Module): string {
	checkNames(module)
	const cases = module.entries.filter((e) => !(module.ownAliases && e.alias))
	const aliases = module.entries.filter((e) => module.ownAliases && e.alias)
	const icons = module.entries.filter((e) => !e.alias && !e.retired).length
	const lines = [
		HEADER,
		`/// An icon from ${module.release}: ${count(icons)} icons, drawn as filled outlines of`,
		"/// Lucide's 2-point strokes, so their weight scales with their size.",
		'///',
		"/// The raw value is the icon's Lucide id, which is also its name in the module's asset",
		'/// catalogue. Ids are permanent: a later release keeps every case, and an id Lucide renames',
		'/// stays as a deprecated alias of the icon it was renamed to.',
		'public enum Icon: String, CaseIterable, Identifiable, Sendable {'
	]
	for (const e of cases) {
		if (e.retired) {
			lines.push(
				`    /// Retired: Lucide no longer has \`${e.id}\`; this keeps the outline it last had.`
			)
		} else if (e.alias) {
			lines.push(
				`    /// Lucide has this icon now, as \`Lucide.Icon.${swiftName(e.alias)}\`; this is a copy of it.`
			)
		}
		lines.push(`    case ${declared(swiftName(e.id))} = "${e.id}"`)
	}
	lines.push(
		'}',
		'',
		'extension Icon {',
		'    /// The Lucide release the icons come from.',
		`    public static let release = "${module.release}"`,
		'',
		"    /// The icon's Lucide id.",
		'    public var id: String { rawValue }',
		'',
		'    /// The icon with the Lucide id or alias `id`, or nil if there is none.',
		'    public init?(id: String) {',
		'        guard let icon = Icon(rawValue: id) ?? Icon.aliases[id] else { return nil }',
		'        self = icon',
		'    }',
		'',
		'    /// Old ids Lucide has renamed, and the icon each now draws.',
		`    public static let aliases: [String: Icon] = [${aliases.length ? '' : ':]'}`
	)
	if (aliases.length) {
		for (const e of aliases) lines.push(`        "${e.id}": .${swiftName(e.alias!)},`)
		lines.push('    ]')
	}
	for (const e of aliases) {
		const target = swiftName(e.alias!)
		lines.push(
			'',
			`    /// \`${e.id}\`, which Lucide renamed \`${e.alias}\`.`,
			`    @available(*, deprecated, renamed: "${target}")`,
			`    public static var ${declared(swiftName(e.id))}: Icon { .${target} }`
		)
	}
	lines.push('}', '')
	return lines.join('\n')
}

/** Icon+Image.swift: the icon as a SwiftUI, AppKit or UIKit template image. */
export function imageSwift(module: Module): string {
	return `${HEADER}
#if canImport(SwiftUI)
import SwiftUI
#endif
#if canImport(AppKit)
import AppKit
#endif
#if canImport(UIKit)
import UIKit
#endif

extension Icon {
    /// The bundle holding the module's asset catalogue.
    static var bundle: Bundle { .module }

    #if canImport(AppKit)
    /// The icon as a template \`NSImage\`, 24 × 24 points, with its vector data.
    public var nsImage: NSImage {
        guard let image = Bundle.module.image(forResource: rawValue) else {
            fatalError(missing(rawValue))
        }
        image.isTemplate = true
        return image
    }
    #endif

    #if canImport(UIKit)
    /// The icon as an \`.alwaysTemplate\` \`UIImage\`, 24 × 24 points, with its vector data.
    public var uiImage: UIImage {
        guard let image = UIImage(named: rawValue, in: .module, compatibleWith: nil) else {
            fatalError(missing(rawValue))
        }
        return image.withRenderingMode(.alwaysTemplate)
    }
    #endif
}

#if canImport(SwiftUI)
extension Image {
    /// \`icon\` as a template image, 24 × 24 points, which takes the foreground style. Make it
    /// \`.resizable()\` to draw it at another size: it keeps its vector data.
    public init(${label(module)} icon: Icon) {
        self = Image(icon.rawValue, bundle: Icon.bundle).renderingMode(.template)
    }
}
#endif

/// Why an icon's image is missing: only a build that doesn't compile asset catalogues loses one.
private func missing(_ id: String) -> String {
    "${module.name}: no image for \\(id). Asset catalogues are compiled by Xcode and xcodebuild, " +
        "not by \`swift build\`."
}
`
}

/** The Contents.json of an asset catalogue folder, laid out the way Xcode writes it: keys in
 * order, with a space before each colon. */
const contents = (folder: { images?: unknown[]; properties?: Record<string, unknown> } = {}) =>
	JSON.stringify(ordered({ ...folder, info: { author: 'xcode', version: 1 } }), null, 2)
		.replaceAll('": ', '" : ')
		.concat('\n')

/** `value` with the keys of every object in it in order. */
function ordered(value: unknown): unknown {
	if (Array.isArray(value)) return value.map(ordered)
	if (value === null || typeof value !== 'object') return value
	return Object.fromEntries(
		Object.keys(value)
			.toSorted()
			.map((k) => [k, ordered((value as Record<string, unknown>)[k])])
	)
}

/** An icon as an SVG: its outline, filled black, in Lucide's 24 x 24 grid. */
export const svg = (geometry: string) =>
	'<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24">' +
	`<path d="${geometry}"/></svg>\n`

/** Every generated file of the module {path: text}, under `dir` (Sources/<name>). */
export function moduleFiles(dir: string, module: Module): Record<string, string> {
	const catalogue = join(dir, `${module.name}.xcassets`)
	const files: Record<string, string> = {
		[join(dir, 'Icon.swift')]: iconSwift(module),
		[join(dir, 'Icon+Image.swift')]: imageSwift(module),
		[join(catalogue, 'Contents.json')]: contents()
	}
	for (const e of module.entries) {
		if (module.ownAliases && e.alias) continue
		const set = join(catalogue, `${e.id}.imageset`)
		files[join(set, 'Contents.json')] = contents({
			images: [{ filename: `${e.id}.svg`, idiom: 'universal' }],
			properties: {
				'preserves-vector-representation': true,
				'template-rendering-intent': 'template'
			}
		})
		files[join(set, `${e.id}.svg`)] = svg(e.geometry)
	}
	return files
}
